function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  for (let i = 0; i < 10; i++) {
    ctx.moveTo(50 + i * 50, H / 2);
    ctx.lineTo(50 + i * 50, H / 2 - 50 - 20 * Math.sin(t + i));
  }
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W / 2, H / 2 + 50 + 20 * Math.sin(t), 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2 - 10, H / 2 + 70 + 20 * Math.sin(t));
  ctx.lineTo(W / 2 - 10, H / 2 + 90 + 20 * Math.sin(t));
  ctx.lineTo(W / 2 + 10, H / 2 + 90 + 20 * Math.sin(t));
  ctx.lineTo(W / 2 + 10, H / 2 + 70 + 20 * Math.sin(t));
  ctx.closePath();
  ctx.stroke();
  ctx.restore();
}
